    if sock is not None:
        sock.close()


def close_on_exec(sock):
    if hasattr(os, 'O_CLOEXEC'):
        try:
            flags = fcntl.fcntl(sock, fcntl.F_GETFD)
        except OSError:
            return
        flags |= fcntl.FD_CLOEXEC
        fcntl.fcntl(sock, fcntl.F_SETFD, flags)


def _ntfy_no_accept(sock, fdset, timeout=0.1):
    """Notify when a socket is ready to accept"""
    if fdset is None:
        return False
    fdset.append(sock)
    try:
        ready, _, _ = select.select([sock], [], [], timeout)
    except (ValueError, OSError):
        return False
    return sock in ready


def _is_socket_readable(sock, timeout=0.1):
    """Check if a socket is readable"""
    try:
        ready, _, _ = select.select([sock], [], [], timeout)
    except (ValueError, OSError):
        return False
    return sock in ready


def is_master_process():
    """Check if the current process is the master process"""
    return os.getpid() == os.getppid()


def is_worker_process():
    """Check if the current process is a worker process"""
    return not is_master_process()


def get_max_open_files():
    """Get the maximum number of open file descriptors"""
    try:
        import resource
        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
        return hard if soft == -1 else soft
    except (ImportError, ValueError):
        return 1024


def get_fd_limits():
    """Get the current file descriptor limits"""
    try:
        import resource
        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
        return soft, hard
    except (ImportError, ValueError):
        return 1024, 1024


def increase_open_files():
    """Increase the open file descriptor limit"""
    try:
        import resource
        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
        if soft < 1024:
            resource.setrlimit(resource.RLIMIT_NOFILE, (hard, hard))
    except (ImportError, ValueError):
        pass


def get_pidfile():
    """Get the PID file path"""
    return os.path.join('/tmp', 'gunicorn.pid')


def write_pidfile(pidfile):
    """Write the PID to the given file"""
    with open(pidfile, 'w') as f:
        f.write(str(os.getpid()))


def remove_pidfile(pidfile):
    """Remove the PID file"""
    try:
        os.remove(pidfile)
    except OSError:
        pass


def get_username(uid):
    """Get the username for a given UID"""
    try:
        return pwd.getpwuid(uid).pw_name
    except KeyError:
        return str(uid)


def get_groupname(gid):
    """Get the group name for a given GID"""
    try:
        import grp
        return grp.getgrgid(gid).gr_name
    except KeyError:
        return str(gid)


def set_owner_process(uid, gid, initgroups=False):
    """Set the owner of the process"""
    if gid:
        if uid:
            try:
                username = get_username(uid)
            except KeyError:
                initgroups = False

        if initgroups:
            os.initgroups(username, gid)
        elif gid != os.getgid():
            os.setgid(gid)

    if uid and uid != os.getuid():
        os.setuid(uid)


def chown(path, uid, gid):
    """Change the owner of a file"""
    os.chown(path, uid, gid)


def to_bytestring(value, encoding='utf-8'):
    """Converts a string argument to a byte string"""
    if isinstance(value, bytes):
        return value
    if not isinstance(value, str):
        raise TypeError('%r is not a string' % value)

    return value.encode(encoding)


def has_fileno(obj):
    if not hasattr(obj, "fileno"):
        return False

    # check BytesIO case and maybe others
    try:
        obj.fileno()
    except (AttributeError, OSError, io.UnsupportedOperation):
        return False

    return True


def warn(msg):
    print("!!!", file=sys.stderr)

    lines = msg.splitlines()
    for i, line in enumerate(lines):
        if i == 0:
            line = "WARNING: %s" % line
        print("!!! %s" % line, file=sys.stderr)

    print("!!!\n", file=sys.stderr)
    sys.stderr.flush()


def make_fail_app(msg):
    msg = to_bytestring(msg)

    def app(environ, start_response):
        start_response("500 Internal Server Error", [
            ("Content-Type", "text/plain"),
            ("Content-Length", str(len(msg)))
        ])
        return [msg]

    return app


def split_request_uri(uri):
    if uri.startswith("//"):
        # When the path starts with //, urlsplit considers it as a
        # relative uri while the RFC says we should consider it as abs_path
        # http://www.w3.org/Protocols/rfc2616/rfc2616-sec5.html#sec5.1.2
        # We use temporary dot prefix to workaround this behaviour
        parts = urllib.parse.urlsplit("." + uri)
        return parts._replace(path=parts.path[1:])

    return urllib.parse.urlsplit(uri)


# From six.reraise
def reraise(tp, value, tb=None):
    try:
        if value is None:
            value = tp()
        if value.__traceback__ is not tb:
            raise value.with_traceback(tb)
        raise value
    finally:
        value = None
        tb = None


def bytes_to_str(b):
    if isinstance(b, str):
        return b
    return str(b, 'latin1')


def unquote_to_wsgi_str(string):
    return urllib.parse.unquote_to_bytes(string).decode('latin-1')
